START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260913182535_AddGloPermissionRolePermissionAndTimeZone') THEN
    CREATE TABLE glo."GloPermission" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "PermissionCode" character varying(100) NOT NULL,
        "Name" character varying(150) NOT NULL,
        "Description" character varying(255),
        "DisplayOrder" smallint NOT NULL DEFAULT 0,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "CreatedOn" timestamptz NOT NULL DEFAULT (timezone('utc', now())),
        CONSTRAINT "PK_GloPermission" PRIMARY KEY ("Id"),
        CONSTRAINT "UX_GloPermission_PermissionCode" UNIQUE ("PermissionCode"),
        CONSTRAINT "CK_GloPermission_Name_NotEmpty" CHECK (length(trim("Name")) > 0),
        CONSTRAINT "CK_GloPermission_PermissionCode_NotEmpty" CHECK (length(trim("PermissionCode")) > 0)
    );
    COMMENT ON TABLE glo."GloPermission" IS 'Global catalog of permissions supported by the FGS platform. Permissions define the actions that can be assigned to security roles.';
    COMMENT ON COLUMN glo."GloPermission"."Id" IS 'Unique identifier for the global permission.';
    COMMENT ON COLUMN glo."GloPermission"."PermissionCode" IS 'Unique system identifier for the permission. Used internally by the application and should not be changed after creation.';
    COMMENT ON COLUMN glo."GloPermission"."Name" IS 'Display name of the permission shown to administrators.';
    COMMENT ON COLUMN glo."GloPermission"."Description" IS 'Optional description explaining what the permission allows the user to do.';
    COMMENT ON COLUMN glo."GloPermission"."DisplayOrder" IS 'Controls the display order of permissions within the permission management interface.';
    COMMENT ON COLUMN glo."GloPermission"."IsActive" IS 'Indicates whether the permission is currently available for assignment to roles.';
    COMMENT ON COLUMN glo."GloPermission"."CreatedOn" IS 'UTC timestamp when the global permission was created.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260913182535_AddGloPermissionRolePermissionAndTimeZone') THEN
    CREATE TABLE glo."GloTimeZone" (
        "Id" smallint GENERATED BY DEFAULT AS IDENTITY,
        "TimeZoneCode" character varying(10) NOT NULL,
        "Name" character varying(50) NOT NULL,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_GloTimeZone" PRIMARY KEY ("Id")
    );
    COMMENT ON TABLE glo."GloTimeZone" IS 'Global reference table containing time zone options available for customer and user selection.';
    COMMENT ON COLUMN glo."GloTimeZone"."Id" IS 'Unique identifier for the time zone.';
    COMMENT ON COLUMN glo."GloTimeZone"."TimeZoneCode" IS 'Short time zone abbreviation used by the application, such as EST, CST, MST, or PST.';
    COMMENT ON COLUMN glo."GloTimeZone"."Name" IS 'User-friendly display name for the time zone.';
    COMMENT ON COLUMN glo."GloTimeZone"."IsActive" IS 'Indicates whether the time zone is currently available for selection.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260913182535_AddGloPermissionRolePermissionAndTimeZone') THEN
    CREATE TABLE glo."GloRolePermission" (
        "RoleId" smallint NOT NULL,
        "PermissionId" bigint NOT NULL,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "CreatedOn" timestamptz NOT NULL DEFAULT (timezone('utc', now())),
        CONSTRAINT "PK_GloRolePermission" PRIMARY KEY ("RoleId", "PermissionId"),
        CONSTRAINT "FK_GloRolePermission_Permission" FOREIGN KEY ("PermissionId") REFERENCES glo."GloPermission" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_GloRolePermission_Role" FOREIGN KEY ("RoleId") REFERENCES glo."GloRole" ("Id") ON DELETE CASCADE
    );
    COMMENT ON TABLE glo."GloRolePermission" IS 'Global default mapping of standard roles to permissions used to seed tenant role permission assignments during onboarding.';
    COMMENT ON COLUMN glo."GloRolePermission"."RoleId" IS 'References the global standard role to which the permission is assigned.';
    COMMENT ON COLUMN glo."GloRolePermission"."PermissionId" IS 'References the global permission assigned to the role.';
    COMMENT ON COLUMN glo."GloRolePermission"."IsActive" IS 'Indicates whether this default role-to-permission assignment is active and should be included when seeding tenant role permission assignments.';
    COMMENT ON COLUMN glo."GloRolePermission"."CreatedOn" IS 'UTC timestamp when the role-to-permission assignment was created.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260913182535_AddGloPermissionRolePermissionAndTimeZone') THEN
    CREATE INDEX "IX_GloPermission_Name" ON glo."GloPermission" ("Name");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260913182535_AddGloPermissionRolePermissionAndTimeZone') THEN
    CREATE INDEX "IX_GloRolePermission_PermissionId" ON glo."GloRolePermission" ("PermissionId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260913182535_AddGloPermissionRolePermissionAndTimeZone') THEN
    CREATE UNIQUE INDEX "IX_GloTimeZone_TimeZoneCode" ON glo."GloTimeZone" ("TimeZoneCode");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260913182535_AddGloPermissionRolePermissionAndTimeZone') THEN
    INSERT INTO glo."GloTimeZone" ("TimeZoneCode", "Name", "IsActive")
    SELECT v."TimeZoneCode", v."Name", TRUE
    FROM (VALUES
        ('EST', 'Eastern Time'),
        ('CST', 'Central Time'),
        ('MST', 'Mountain Time'),
        ('PST', 'Pacific Time'),
        ('AKST', 'Alaska Time'),
        ('HST', 'Hawaii Time')
    ) AS v("TimeZoneCode", "Name")
    WHERE NOT EXISTS (
        SELECT 1
        FROM glo."GloTimeZone" t
        WHERE t."TimeZoneCode" = v."TimeZoneCode"
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260913182535_AddGloPermissionRolePermissionAndTimeZone') THEN
    INSERT INTO setup."__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260913182535_AddGloPermissionRolePermissionAndTimeZone', '10.0.8');
    END IF;
END $EF$;
COMMIT;

